class GeneralTaskSchema(BaseModel):
    """
    Base schema for all workflow tasks. All task-specific schemas extend this schema via allOf reference. These fields are available on every task type and control identification, execution priority, and visual positioning in the workflow canvas.
    """

    id: int
    """
    Integer ID used for task linkage mapping during import/export. This ID is temporary and used only to establish relationships between tasks (via linkage.json). On import, Rails generates new database IDs and updates all linkage references accordingly. When creating workflows, use sequential integers starting from 1.
    """
    name: str | None = "task"
    """
    Display name of the task shown in the workflow canvas UI. Supports Liquid templating for dynamic names. Best practice: use descriptive names that indicate the task's purpose.
    """
    action_type: ActionType
    """
    Specifies which task handler processes this task. Each action_type corresponds to a specific task schema (e.g., 'Query' uses query.json, 'Data::Aqua' uses data/aqua.json). The action_type determines what parameters are available and how the task executes.
    """
    priority: Priority | None = "Medium"
    """
    Execution priority affecting task scheduling order. 'High' priority tasks are scheduled before 'Medium' and 'Low' when multiple tasks are ready to execute. Use 'High' for time-sensitive operations, 'Low' for background/cleanup tasks.
    """
    css: Annotated[
        GeneralTaskSchemaCss, Field(title="GeneralTaskSchemaCss", validate_default=True)
    ] = {"top": "100px", "left": "200px"}
    """
    Visual positioning for the task node on the workflow canvas editor. Values are CSS pixel strings. Tasks should be spaced ~150-200px apart for readability. The canvas origin (0,0) is top-left.
    """
    call_type: CallType5 | None = "SOAP"
    """
    API protocol for Zuora API calls. SOAP uses Zuora SOAP API, REST uses Zuora REST API. Not all tasks support both.
    """
    concurrent_limit: Annotated[int | None, Field(ge=1, le=9999999)] = 9999999
    """
    Maximum concurrent executions of this task. Limits parallel processing for rate-limited APIs or resource-intensive operations. Valid range: 1-9999999.
    """
    tags: list[str] | None = []
    """
    Task-level tags for categorization. These are separate from workflow_tags in parameters.
    """
    zuora_org_id: str | None = None
    """
    Zuora organization ID for multi-org tenant environments. When set, the task executes in the context of this specific org. Supports Liquid templating to dynamically select org based on workflow data. Use null or omit for single-org tenants or to inherit from workflow context.
    """
    zuora_org_ids: list[str] | None = []
    """
    Array of Zuora organization IDs for tasks that operate across multiple orgs in multi-org tenant environments. Each string can be a literal org ID or Liquid template expression. Empty array indicates single-org operation.
    """


