class WorkflowConfigurationParameters(BaseModel):
    """
    Input parameters and event configuration. Contains: input field definitions (accessible as Data.<FieldName>), event_triggers (array of event names), and event_parameters (mapping event fields to Data paths). Internal runtime fields (skipping_check, callout_response, etc.) are omitted from the export when at their default values.
    """

    model_config = ConfigDict(
        extra="allow",
    )
    fields: list[Any] | None = []
    """
    Input field definitions accessible as Data.<FieldName> during workflow execution.
    """
    event_triggers: list[str] | None = []
    """
    Array of Zuora event names that trigger this workflow (e.g. 'BillingRunCompletion').
    """
    event_parameters: list[Any] | None = []
    """
    Mapping of event fields to Data paths. Each entry specifies eventName and params array.
    """
    skipping_check: str | None = "none"
    """
    Controls duplicate-run prevention. 'none' disables skipping; other values skip if a run is already pending/running.
    """
    merge_task_ids: list[Any] | None = []
    """
    Task IDs whose outputs are merged into the workflow data context on completion.
    """
    disable_pending_status: bool | None = False
    """
    When true, workflow runs skip the 'Pending' status and go directly to 'Processing'.
    """
    secure_error_msgs: str | None = "false"
    """
    When 'true', error messages are sanitized before being returned to callers.
    """
    legacy_boolean_input: bool | None = False
    """
    Enable legacy boolean input handling for older workflow versions.
    """
    callout_response: str | None = "workflow instance"
    """
    What to return in the callout HTTP response. 'workflow instance' returns the workflow run object.
    """
    file_encryption: str | None = None
    """
    Encryption key reference for file outputs. null means no encryption.
    """
    show_run_prompt: str | bool | None = None
    """
    When set, displays a prompt dialog before manual workflow runs.
    """


