class WorkflowConfiguration(BaseModel):
    """
    Configuration for workflow triggers, schedule, parameters, and runtime settings. Defines how the workflow is invoked and its execution behavior.
    """

    id: int | None = None
    """
    Unique identifier for the workflow. Auto-generated on creation.
    """
    name: str
    """
    Name of the workflow. Must be unique within the tenant.
    """
    description: str | None = ""
    """
    Description of the workflow purpose and functionality.
    """
    parameters: Annotated[
        WorkflowConfigurationParameters | None,
        Field(title="WorkflowConfigurationParameters", validate_default=True),
    ] = {}
    """
    Input parameters and event configuration. Contains: input field definitions (accessible as Data.<FieldName>), event_triggers (array of event names), and event_parameters (mapping event fields to Data paths). Internal runtime fields (skipping_check, callout_response, etc.) are omitted from the export when at their default values.
    """
    data: Annotated[
        WorkflowConfigurationData | None,
        Field(title="WorkflowConfigurationData", validate_default=True),
    ] = {}
    """
    Initial data context for the workflow. Merged with incoming parameters on workflow start.
    """
    type: str | None = "Workflow::Setup"
    """
    Internal workflow type. Workflow::Setup is standard workflow definition.
    """
    call_type: CallType6 | None = "BATCH"
    """
    Workflow execution mode determining performance characteristics and available triggers. BATCH for large data (minutes-hours), REALTIME for high concurrency (seconds-minutes), UIACTION for Zuora UI buttons.
    """
    ondemand_trigger: bool | None = True
    """
    Enable manual triggering via API (POST /workflows/{id}/run) or UI Run button. Available for BATCH and REALTIME workflows.
    """
    callout_trigger: bool | None = False
    """
    Enable triggering by external webhooks via unique workflow callout URL. When enabled, workflow receives callout data in Data context. Not available for BATCH workflows.
    """
    scheduled_trigger: bool | None = False
    """
    Enable scheduled execution using cron expression. Requires interval and timezone to be set. Available for BATCH and REALTIME workflows.
    """
    interval: str | None = None
    """
    Cron expression for scheduled workflows (5 fields: minute hour day month weekday). Required when scheduled_trigger is true.
    """
    timezone: Timezone | None = None
    """
    Timezone for scheduled workflow execution. Required when scheduled_trigger is true. Determines when cron schedule fires.
    """
    event_trigger: bool | None = False
    """
    Enable triggering by Zuora billing events. When true, requires parameters.event_triggers array with event names. Event data available in Data context based on parameters.event_parameters mapping.
    """
    status: Status | None = "Inactive"
    """
    Workflow activation status. Only 'Active' workflows can be triggered. Set to 'Inactive' during development/testing.
    """
    css: Annotated[dict[str, Any] | None, Field(title="WorkflowConfigurationCss")] = {
        "top": "40px",
        "left": "35px",
    }
    """
    CSS positioning for workflow canvas. Contains top/left position of the workflow setup node.
    """
    ui_trigger: bool | None = False
    """
    Enable triggering from Zuora UI buttons. Set to true for UIACTION call_type workflows.
    """
    notifications: Annotated[
        WorkflowConfigurationNotifications | None,
        Field(title="WorkflowConfigurationNotifications", validate_default=True),
    ] = {}
    """
    Email notification configuration for workflow lifecycle events (start, complete, error).
    """
    priority: Priority1 | None = "Medium"
    """
    Execution priority. High priority workflows are scheduled before Medium/Low when resources are constrained.
    """
    delete_ttl: int | None = 30
    """
    Days to retain workflow run history before automatic deletion. Range: 1-365.
    """
    version: str | None = "0.0.1"
    """
    Semantic version for tracking workflow changes.
    """
    zuora_org_id: str | None = None
    """
    Zuora organization ID for multi-org environments.
    """
    ui_pages: Annotated[
        WorkflowConfigurationUipages | None,
        Field(title="WorkflowConfigurationUipages", validate_default=True),
    ] = {}
    """
    UI button configuration for UIACTION workflows. Maps Zuora UI page names to button labels.
    """
    solution_id: str | None = None
    """
    Associated solution ID for marketplace/packaged workflows.
    """
    extension_id: str | None = None
    """
    Associated extension ID for Zuora platform extensions.
    """
    zuora_org_ids: list[str] | None = []
    """
    Array of Zuora organization IDs for multi-org access.
    """


class WorkflowDefinition(BaseModel):
    """
    Metadata for a workflow definition including name, description, categorization, and access control. This is the top-level container for workflow configuration used in export/import.
    """

    name: str
    """
    Display name of the workflow definition. Must be unique within tenant. Shown in workflow list and used for identification.
    """
    description: str | None = ""
    """
    Description of what the workflow does. Displayed in workflow list, details page, and UI hover tooltips.
    """
    category: str | None = "Default"
    """
    Category to organize workflow definitions in the UI. Workflows are grouped by category in the left navigation.
    """
    ui_page_roles: list[str] | None = []
    """
    User roles that can access UI pages in this workflow. Empty array means all roles can access. Use for role-based access control on interactive workflows.
    """


