class WorkflowExportStructure(BaseModel):
    """
    Complete workflow export structure matching Workflow::Setup.export method. Use this schema for importing/exporting complete workflows including all tasks and linkages.
    """

    workflow_definition: WorkflowDefinition
    """
    Workflow definition metadata (name, description, category, ui_page_roles). Defines how workflow appears in UI.
    """
    workflow: WorkflowConfiguration
    """
    Workflow configuration including triggers (on-demand, scheduled, callout, event), execution settings (sync/async, priority), and input parameters.
    """
    tasks: list[WorkflowExportStructureTask]
    """
    Array of task definitions. Each task has an 'id' used for linkage mapping (replaced with actual DB IDs on import). See task-specific schemas for parameter details.
    """
    linkages: list[TaskLinkage]
    """
    Array of task connections defining workflow execution flow. Linkages use task IDs from the tasks array.
    """


